sql_excerpt:
options.connection.client.$queryRawUnsafe(
      "-- @tenancy: prisma readiness probe\nSELECT 1 AS ready",
    )

this.#prisma.$queryRaw<ProcessManagerInstance[]>(
      Prisma.sql`
        SELECT *
        FROM "ProcessManagerInstance"
        WHERE "nextWakeAt" <= ${asDate(params.now)}
        ${processNameFilter}
        ORDER BY "nextWakeAt" ASC, "processName" ASC,
                 "projectId" ASC, "processKey" ASC
        LIMIT ${params.limit}
      `,
    )

this.#prisma.$executeRaw`
      DELETE FROM "ProcessManagerOutbox"
      WHERE "id" IN (
        SELECT "id" FROM "ProcessManagerOutbox"
        WHERE "status" = 'dispatched'::"ProcessManagerOutboxStatus"
          AND "dispatchedAt" < ${asDate(params.before)}
        LIMIT ${params.limit}
      )
      -- @tenancy: process-manager retention sweep, dispatched outbox (system-owned maintenance)
    `

this.#prisma.$executeRaw`
      DELETE FROM "ProcessManagerOutbox"
      WHERE "id" IN (
        SELECT "id" FROM "ProcessManagerOutbox"
        WHERE "status" IN (
            'dead'::"ProcessManagerOutboxStatus",
            'discarded'::"ProcessManagerOutboxStatus"
          )
          AND "updatedAt" < ${asDate(params.before)}
        LIMIT ${params.limit}
      )
      -- @tenancy: process-manager retention sweep, dead outbox (system-owned maintenance)
    `

this.#prisma.$executeRaw`
      DELETE FROM "ProcessManagerInbox"
      WHERE "id" IN (
        SELECT "id" FROM "ProcessManagerInbox"
        WHERE "consumedAt" < ${asDate(params.before)}
        LIMIT ${params.limit}
      )
      -- @tenancy: process-manager retention sweep, consumed inbox (system-owned maintenance)
    `

this.prisma.$executeRaw`
      UPDATE "ScheduledJob"
      SET "active" = ${active}
      WHERE "id" = ${id}
        AND "projectId" = ${projectId}
      -- @tenancy: scheduler cross-tenant ops control (system-owned, ops:manage)
    `

this.database.$executeRawUnsafe(
          `-- @tenancy: cross-tenant process-manager housekeeping; ops-gated\nVACUUM (ANALYZE) "${table}"`,
        )

this.prisma.$queryRaw<
        Array<{
          processName: string;
          pendingMessages: number;
          overduePending: number;
          lapsedLeases: number;
          deadMessages: number;
        }>
      >(Prisma.sql`
        -- @tenancy: cross-tenant ops fleet counts; the surface is ops-gated
        SELECT "processName",
               COUNT(*) FILTER (WHERE "status" = 'pending')::int AS "pendingMessages",
               COUNT(*) FILTER (
                 WHERE "status" = 'pending'
                   AND "nextAttemptAt" < ${overduePendingBefore}
                   AND ("leasedUntil" IS NULL OR "leasedUntil" < ${now})
               )::int AS "overduePending",
               COUNT(*) FILTER (
                 WHERE "status" = 'pending' AND "leasedUntil" < ${now}
               )::int AS "lapsedLeases",
               COUNT(*) FILTER (WHERE "status" = 'dead')::int AS "deadMessages"
        FROM "ProcessManagerOutbox"
        WHERE "status" IN ('pending', 'dead')
        GROUP BY "processName"
      `)

this.prisma.$queryRaw<
        Array<{
          processName: string;
          projectId: string;
          processKey: string;
          tenantId: string;
          revision: number;
          nextWakeAt: Date | null;
          updatedAt: Date;
        }>
      >(Prisma.sql`
        -- @tenancy: cross-tenant ops listing; rows carry their project identity
        SELECT "processName", "projectId", "processKey", "tenantId",
               "revision", "nextWakeAt", "updatedAt"
        FROM "ProcessManagerInstance"
        WHERE 1 = 1
        ${nameFilter}
        ${searchFilter}
        ORDER BY "updatedAt" DESC
        LIMIT ${params.pageSize}
        OFFSET ${(params.page - 1) * params.pageSize}
      `)

this.prisma.$queryRaw<
        Array<{
          processName: string;
          projectId: string;
          processKey: string;
          pending: number;
          dead: number;
        }>
      >(Prisma.sql`
        -- @tenancy: scoped to the page's (processName, projectId, processKey) tuples above
        SELECT "processName", "projectId", "processKey",
               COUNT(*) FILTER (WHERE "status" = 'pending')::int AS "pending",
               COUNT(*) FILTER (WHERE "status" = 'dead')::int AS "dead"
        FROM "ProcessManagerOutbox"
        WHERE "status" IN ('pending', 'dead')
          AND ("processName", "projectId", "processKey") IN (${pairs})
        GROUP BY "processName", "projectId", "processKey"
      `)

this.prisma.$queryRaw<
      Array<{
        processName: string;
        projectId: string;
        processKey: string;
        nextWakeAt: Date;
      }>
    >(Prisma.sql`
      -- @tenancy: cross-tenant ops listing; rows carry their project identity
      SELECT "processName", "projectId", "processKey", "nextWakeAt"
      FROM "ProcessManagerInstance"
      WHERE "nextWakeAt" IS NOT NULL
      ORDER BY "nextWakeAt" ASC
      LIMIT ${Math.min(Math.max(params.limit, 1), 200)}
    `)

this.prisma.$queryRaw<
        Array<
          Omit<
            DeadOutboxMessageView,
            "nextAttemptAt" | "leasedUntil" | "createdAt" | "updatedAt"
          > & {
            nextAttemptAt: Date;
            leasedUntil: Date | null;
            createdAt: Date;
            updatedAt: Date;
            traceCarrier: unknown;
          }
        >
      >(Prisma.sql`
        -- @tenancy: cross-tenant ops dead-letter read; the surface is ops-gated
        SELECT "id", "processName", "projectId", "processKey", "messageKey",
               "intentType", "status", "attempts", "nextAttemptAt",
               "leasedUntil", "createdAt", "updatedAt", "sourceEventId",
               "traceCarrier", "payload"
        FROM "ProcessManagerOutbox"
        WHERE "status" = 'dead'
        ${nameFilter}
        ORDER BY "updatedAt" DESC, "id" DESC
        LIMIT ${params.pageSize}
        OFFSET ${(params.page - 1) * params.pageSize}
      `)
